{
  "title": "Discussion on tax shortcuts, domain purchase, and low‑profit app idea",
  "topics": [
    {
      "id": "tax-shortcut",
      "title": "Using aunt Svetlana to reduce tax penalties",
      "claims": [
        {
          "text": "Paying aunt Svetlana 500 UAH helped avoid larger penalties by having her re‑file declarations.",
          "evidence": [1]
        },
        {
          "text": "The inspector ignored the author's declarations for 1.5 years and was later reprimanded, leading to a thorough check of all years.",
          "evidence": [1]
        },
        {
          "text": "With Svetlana's help the author paid about 1000 UAH instead of the full fines.",
          "evidence": [1]
        }
      ]
    },
    {
      "id": "domain-fundraising",
      "title": "Funding a domain purchase with tax calculator earnings",
      "claims": [
        {
          "text": "User U2 mentions not having bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "User U1 suggests that buying a tax calculator could generate money for a domain.",
          "evidence": [4]
        },
        {
          "text": "User U4 doubts anyone will buy a domain for this purpose.",
          "evidence": [9]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Low profitability of a simple web app",
      "claims": [
        {
          "text": "Web is the easiest platform but far less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "SEO is poor; even on the 10th Google page the site is not found.",
          "evidence": [11]
        },
        {
          "text": "No external traffic sources (Instagram, Threads, contextual ads) are available.",
          "evidence": [11]
        },
        {
          "text": "User acquisition is near zero because a paywall appears within the first seconds.",
          "evidence": [11]
        },
        {
          "text": "Conversion is presumed zero; the product offers little simplification and lacks integrations.",
          "evidence": [11]
        },
        {
          "text": "Successful cases involve fast delivery (< 1 week) and cross‑platform stacks like Flutter.",
          "evidence": [12]
        },
        {
          "text": "U4 questions the seriousness of the effort, likening it to a scam.",
          "evidence": [16, 32]
        },
        {
          "text": "U1 doubts anyone would buy the app, betting on a low chance of sales.",
          "evidence": [17]
        }
      ]
    },
    {
      "id": "currency-support",
      "title": "Calculator limited to UAH‑only FOP",
      "claims": [
        {
          "text": "The tax calculator works only with Ukrainian‑hryvnia FOPs; the author had to convert transactions using daily exchange rates.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "source-code-password",
      "title": "Questions about source code access and password",
      "claims": [
        {
          "text": "U4 says the app’s source code is hidden and the only password is stored locally as a 100 % discount promo code.",
          "evidence": [20]
        },
        {
          "text": "U1 asks if the password can be found by searching the source code.",
          "evidence": [21]
        },
        {
          "text": "U4 replies sarcastically that they did not pay 299 UAH for it.",
          "evidence": [22]
        },
        {
          "text": "U5 labels the app as a pirated bundle.",
          "evidence": [24]
        },
        {
          "text": "U1 predicts most LinkedIn users could hack the app easily.",
          "evidence": [28]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Will the source code ever be publicly released or is the password permanently hidden?",
      "evidence": [21, 22]
    }
  ]
}
